BEGIN;
\ir helpers.sql
\ir fixtures.sql
DO $$ DECLARE a uuid; b uuid; host uuid; operator uuid; funder uuid; phone uuid; old_location uuid; new_location uuid; old_lrev uuid; orgrev uuid; orgedit uuid; run uuid; result_a uuid; result_b uuid; failed uuid; body jsonb; days jsonb; rev uuid; owner uuid; simultaneous uuid; moved uuid; restored uuid; area_rev uuid; area_id uuid; detail jsonb; languages uuid; original uuid; translated uuid; review uuid; BEGIN
 a:=pg_temp.save('territory','{"code":"integrated-a","name":"Area A","timezone_name":"Europe/Rome"}');PERFORM pg_temp.publish(a);SELECT entity_id INTO a FROM governance.entity_revisions WHERE revision_id=a;
 b:=pg_temp.save('territory','{"code":"integrated-b","name":"Area B","timezone_name":"Europe/Rome"}');PERFORM pg_temp.publish(b);SELECT entity_id INTO b FROM governance.entity_revisions WHERE revision_id=b;
 orgrev:=pg_temp.save('organization','{"name":"Building host"}');PERFORM pg_temp.publish(orgrev);SELECT entity_id INTO host FROM governance.entity_revisions WHERE revision_id=orgrev;
 orgrev:=pg_temp.save('organization','{"name":"Service operator","contacts":[{"channel_type":"phone","value":"original endpoint","purpose_code":"appointment"}]}');PERFORM pg_temp.publish(orgrev);SELECT entity_id INTO operator FROM governance.entity_revisions WHERE revision_id=orgrev;SELECT component_id INTO phone FROM data.contact_entries WHERE revision_id=orgrev;
 languages:=pg_temp.save('organization','{"name":"Funding partner"}');PERFORM pg_temp.publish(languages);SELECT entity_id INTO funder FROM governance.entity_revisions WHERE revision_id=languages;
 INSERT INTO sources.processing_runs(run_kind,capture_id,processor_version,config_hash,status) VALUES('geocode','52000000-0000-0000-0000-000000000001','synthetic-geocoder-v1','context-v1','succeeded') RETURNING run_id INTO run;
 INSERT INTO geo.geocoding_results(run_id,provider,request_hash,input_address,context,latitude,longitude,precision,status,payload_ref,retrieved_at) VALUES(run,'provider-a','a','Synthetic address','{}',41.9,12.5,'building','succeeded','fixture:geo-a','2026-01-01Z') RETURNING result_id INTO result_a;
 INSERT INTO geo.geocoding_results(run_id,provider,request_hash,input_address,context,latitude,longitude,precision,status,payload_ref,retrieved_at) VALUES(run,'provider-b','b','Synthetic address','{}',41.91,12.51,'street','succeeded','fixture:geo-b','2026-01-01Z') RETURNING result_id INTO result_b;
 INSERT INTO geo.geocoding_results(run_id,provider,request_hash,input_address,context,precision,status,payload_ref,retrieved_at) VALUES(run,'provider-a','failed','Unknown address','{}','unknown','failed','fixture:geo-failed','2026-01-01Z') RETURNING result_id INTO failed;
 old_lrev:=pg_temp.save('location',jsonb_build_object('name','Original building','location_kind','building','coordinate_state','known','latitude',41.9,'longitude',12.5,'selected_geocoding_result_id',result_a,'organizations',jsonb_build_array(jsonb_build_object('organization_id',host,'role_code','host'))));PERFORM pg_temp.publish(old_lrev);SELECT entity_id INTO old_location FROM governance.entity_revisions WHERE revision_id=old_lrev;
 languages:=pg_temp.save('location','{"name":"Destination building","location_kind":"building","coordinate_state":"unknown"}');PERFORM pg_temp.publish(languages);SELECT entity_id INTO new_location FROM governance.entity_revisions WHERE revision_id=languages;
 PERFORM pg_temp.assert_true((SELECT selected_geocoding_result_id=result_a AND public.ST_X(point)=longitude AND public.ST_Y(point)=latitude FROM data.location_revisions WHERE revision_id=old_lrev),'AC17 chosen provider and scalar-derived point');
 PERFORM pg_temp.assert_true((SELECT count(*)=3 FROM geo.geocoding_results WHERE run_id=run),'AC17 competing and failed results retained');
 PERFORM pg_temp.expect_error(format('SELECT pg_temp.save(%L,%L)','location',jsonb_build_object('name','Mismatched choice','location_kind','building','coordinate_state','known','latitude',0,'longitude',0,'selected_geocoding_result_id',result_a)),'23514','selected_coordinates_mismatch');
 SELECT jsonb_agg(jsonb_build_object('weekday',n,'state',CASE WHEN n=1 THEN 'intervals' ELSE 'closed' END,'completeness','complete','intervals',CASE WHEN n=1 THEN '[{"opens":"09:00","closes":"17:00"}]'::jsonb ELSE '[]'::jsonb END)) INTO days FROM generate_series(1,7)n;
 body:=jsonb_build_object('name','Place-specific offer','description','Integrated physical offer','delivery_mode','in_person','place',jsonb_build_object('location_id',old_location),'territories',jsonb_build_array(a,b),'coverage',jsonb_build_array(jsonb_build_object('territory_id',a,'description','Coverage only A')),'organizations',jsonb_build_array(jsonb_build_object('organization_id',operator,'role_code','operator'),jsonb_build_object('organization_id',funder,'role_code','funder')),'contact_links',jsonb_build_array(jsonb_build_object('target_entity_id',operator,'target_contact_component_id',phone,'purpose_code','appointment')),'cost_state','variable','cost_note','Ask about costs','conditions','[{"condition_kind":"appointment","requirement_state":"required","details":"Call first"},{"condition_kind":"referral","requirement_state":"not_required","details":"Referral optional"},{"condition_kind":"document","requirement_state":"conditional","details":"Bring documents if available"},{"condition_kind":"eligibility","requirement_state":"unknown","details":"Ask about geographic access"}]'::jsonb,'schedules',jsonb_build_array(jsonb_build_object('timezone','Europe/Rome','completeness','complete','days',days,'evidence','[{"assertion_id":"57000000-0000-0000-0000-000000000002","role":"supporting"},{"assertion_id":"57000000-0000-0000-0000-000000000003","role":"contradicting"}]'::jsonb)));
 rev:=pg_temp.save('service',body);PERFORM pg_temp.publish(rev);SELECT entity_id INTO owner FROM governance.entity_revisions WHERE revision_id=rev;
 simultaneous:=pg_temp.save('service',jsonb_set(body,'{place,location_id}',to_jsonb(new_location)));PERFORM pg_temp.publish(simultaneous);SELECT entity_id INTO simultaneous FROM governance.entity_revisions WHERE revision_id=simultaneous;
 PERFORM pg_temp.assert_true(owner<>simultaneous,'AC01 simultaneous places have distinct identities');
 languages:=pg_temp.save('service',jsonb_build_object('name','Independent legal advice','description','Different provider in same building','delivery_mode','in_person','place',jsonb_build_object('location_id',old_location),'territories',jsonb_build_array(a)));PERFORM pg_temp.publish(languages);
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM api.published_services s JOIN data.service_places p USING(revision_id) WHERE p.location_id=old_location),'AC01 multiple independent offers in shared building');
 PERFORM pg_temp.assert_true(NOT EXISTS(SELECT FROM data.service_organizations WHERE revision_id=rev AND organization_id=host),'AC10 host never inferred as provider');
 detail:=api.service_detail(owner,NULL,'2026-01-05 10:00Z');
 PERFORM pg_temp.assert_true(jsonb_array_length(detail->'organizations')=2 AND detail->>'cost_state' IS NULL AND detail#>>'{cost,state}'='variable' AND jsonb_array_length(detail->'conditions')=4,'AC10 AC12 distinct roles and structured conditions/cost');
 PERFORM pg_temp.assert_true(jsonb_array_length(detail->'territories')=2 AND jsonb_array_length(detail->'coverage')=1,'AC16 membership and coverage distinct');
 PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM geo.service_memberships WHERE entity_id=owner AND revision_id=rev),'AC16 overlap retains one entity');
 PERFORM pg_temp.assert_true((SELECT count(DISTINCT e.evidence_role)=2 FROM data.schedules s JOIN governance.value_evidence e USING(value_decision_id) WHERE s.revision_id=rev),'AC07 conflicting assertions survive selected schedule');
 INSERT INTO sources.captures(dataset_id,retrieved_at,artifact_uri,content_hash,media_type,retrieval_status,source_metadata_snapshot) VALUES('51000000-0000-0000-0000-000000000001','2026-01-03Z','fixture:unavailable','missing','application/json','failed','{"http_status":404}');
 PERFORM pg_temp.assert_true((SELECT revision_id=rev FROM governance.published_heads WHERE entity_id=owner) AND (SELECT operational_status='unknown' FROM data.service_revisions WHERE revision_id=rev),'AC08 source disappearance does not close or delete');
 languages:=governance.save_revision('service',NULL,NULL,NULL,'{"name":"No evidence","description":"Complete fields but no source","delivery_mode":"telephone","contacts":[{"channel_type":"phone","value":"contact"}]}','Draft without evidence');
 PERFORM pg_temp.expect_error(format('SELECT governance.review_revision(%L,NULL,%L,%L)',languages,'approved','Do not approve unsupported data'),'23514','missing_evidence');
 PERFORM pg_temp.assert_true(EXISTS(SELECT FROM governance.entity_revisions WHERE revision_id=languages) AND NOT EXISTS(SELECT FROM governance.published_heads WHERE revision_id=languages),'AC04 unsupported record retained in draft');
 moved:=pg_temp.save('service',jsonb_set(body,'{place,location_id}',to_jsonb(new_location)),owner,rev,rev);PERFORM pg_temp.publish(moved,rev);
 PERFORM pg_temp.assert_true(api.service_detail(owner)#>>'{place,location_id}'=new_location::text AND EXISTS(SELECT FROM data.service_places WHERE revision_id=rev AND location_id=old_location),'AC02 published move retains identity/history');
 PERFORM pg_temp.assert_true((SELECT revision_id=old_lrev FROM governance.published_heads WHERE entity_id=old_location) AND (SELECT count(*)=1 FROM api.published_services s JOIN data.service_places p USING(revision_id) WHERE p.location_id=old_location),'AC02 old location and independent service unchanged');
 orgedit:=pg_temp.save('organization',jsonb_build_object('name','Updated shared operator','contacts',jsonb_build_array(jsonb_build_object('component_id',phone,'channel_type','phone','value','new endpoint'))),operator,orgrev,orgrev);PERFORM pg_temp.publish(orgedit,orgrev);
 restored:=governance.restore_revision(rev,moved,moved,'Restore complete approved aggregate');
 PERFORM pg_temp.assert_true(api.service_detail(owner)#>>'{place,location_id}'=new_location::text,'AC06 restore pending until exact approval');PERFORM pg_temp.publish(restored,moved);
 detail:=api.service_detail(owner,NULL,'2026-01-05 10:00Z');
 PERFORM pg_temp.assert_true(detail#>>'{place,location_id}'=old_location::text AND detail#>>'{opening,status}'='open' AND jsonb_array_length(detail->'conditions')=4 AND detail#>>'{contacts,0,value}'='new endpoint','AC06 owned hours/access/place restored and shared endpoint stays current');
 PERFORM pg_temp.assert_true((SELECT restored_from_revision_id=rev AND actor_id IS NOT NULL FROM governance.entity_revisions WHERE revision_id=restored),'AC06 exact restore origin/actor');
 area_rev:=pg_temp.save('service',jsonb_build_object('name','Mobile offer A','description','Known area, uncertain stop','delivery_mode','itinerant','territories',jsonb_build_array(a),'place',jsonb_build_object('territory_id',a,'area_description','Neighborhood A'),'schedules',body->'schedules'));PERFORM pg_temp.publish(area_rev);SELECT entity_id INTO area_id FROM governance.entity_revisions WHERE revision_id=area_rev;
 detail:=api.service_detail(area_id,NULL,'2026-01-06 10:00Z');PERFORM pg_temp.assert_true(detail#>>'{opening,status}'='closed' AND detail#>>'{place,location_id}' IS NULL AND detail#>>'{place,area_description,text}'='Neighborhood A','AC15 non-operating mobile area has no invented point');
 PERFORM pg_temp.assert_true(EXISTS(SELECT FROM jsonb_array_elements(api.directory_snapshot(a,NULL,'{}','2026-01-06 10:00Z')->'services')s WHERE s->>'service_id'=area_id::text),'AC15 closed mobile place remains discoverable');
 PERFORM pg_temp.assert_true(NOT EXISTS(SELECT FROM jsonb_array_elements(api.directory_snapshot(a,NULL,'{}','2026-01-06 10:00Z',true)->'services')s WHERE s->>'service_id'=area_id::text),'AC15 separate explicit open filter');
 languages:=pg_temp.save('service','{"name":"Online access","description":"No coordinates needed","delivery_mode":"online","contacts":[{"channel_type":"web","value":"https://example.invalid/online"}]}');PERFORM pg_temp.publish(languages);
 PERFORM pg_temp.assert_true((SELECT count(*)=0 FROM data.service_places WHERE revision_id=languages),'AC03 online offer has no fabricated geography');
 PERFORM governance.register_language('ar','العربية','Arabic','rtl','Synthetic language');
 PERFORM governance.register_language('es','Español','Spanish','ltr','Synthetic language');
 PERFORM governance.prioritize_language(a,'ar',1,true,'Priority in area A');
 PERFORM governance.prioritize_language(b,'es',1,true,'Different priority in area B');
 PERFORM pg_temp.assert_true(EXISTS(SELECT FROM i18n.territory_language_priorities WHERE territory_id=a AND language_code='ar') AND EXISTS(SELECT FROM i18n.territory_language_priorities WHERE territory_id=b AND language_code='es'),'AC20 territorial translation priorities differ');
 original:=pg_temp.save('service','{"name":"Original name","description":"Original description","delivery_mode":"telephone","contacts":[{"channel_type":"phone","value":"contact"}]}');PERFORM pg_temp.publish(original);
 SELECT description_content_id INTO translated FROM data.service_revisions WHERE revision_id=original;
 translated:=governance.propose_translation(translated,'ar','وصف','human',NULL,NULL,'Description only');review:=governance.review_translation(translated,'approved','Approve partial translation');PERFORM governance.publish_translation(translated,review,NULL,'Publish partial');SELECT entity_id INTO original FROM governance.entity_revisions WHERE revision_id=original;
 detail:=api.service_detail(original,'ar');PERFORM pg_temp.assert_true(detail#>>'{name,text}'='Original name' AND detail#>>'{description,text}'='وصف','AC20 translated description with untranslated name');
END $$;
DO $$ DECLARE territory uuid; vr uuid; vocab uuid; axis uuid; rev uuid; parent uuid; child uuid; source uuid; copy uuid; copy_vocab uuid; copy_vr uuid; copy_axis uuid; copy_child uuid; copy_revision uuid; changed uuid; next_copy uuid; members jsonb; axes jsonb;
BEGIN
 SELECT entity_id INTO territory FROM geo.territories WHERE code='integrated-b';
 vr:=pg_temp.save('taxonomy_vocabulary','{"name":"Integrated hierarchy","code":"integrated-vocabulary"}');PERFORM pg_temp.publish(vr);SELECT entity_id INTO vocab FROM governance.entity_revisions WHERE revision_id=vr;axis:=governance.create_taxonomy_axis(vocab,'need');
 rev:=pg_temp.save('taxonomy_term',jsonb_build_object('name','Support','code','support','vocabulary_id',vocab,'axis_id',axis));PERFORM pg_temp.publish(rev);SELECT entity_id INTO parent FROM governance.entity_revisions WHERE revision_id=rev;
 members:=jsonb_build_array(jsonb_build_object('term_id',parent,'revision_id',rev));
 rev:=pg_temp.save('taxonomy_term',jsonb_build_object('name','Advice','code','advice','vocabulary_id',vocab,'axis_id',axis));PERFORM pg_temp.publish(rev);SELECT entity_id INTO child FROM governance.entity_revisions WHERE revision_id=rev;members:=members||jsonb_build_array(jsonb_build_object('term_id',child,'revision_id',rev));
 source:=governance.freeze_taxonomy_release(vr,'v1',jsonb_build_array(jsonb_build_object('axis_id',axis,'label','Need')),members,jsonb_build_array(jsonb_build_object('child',child,'parent',parent)),'Approve source hierarchy');
 copy:=governance.fork_taxonomy_release(source,territory,'integrated-independent-copy','v1','Copy for local adaptation');
 SELECT vocabulary_id,vocabulary_revision_id INTO copy_vocab,copy_vr FROM taxonomy.releases WHERE release_id=copy;
 SELECT entity_id,axis_id INTO copy_child,copy_axis FROM taxonomy.terms WHERE vocabulary_id=copy_vocab AND code='advice';SELECT revision_id INTO copy_revision FROM governance.published_heads WHERE entity_id=copy_child;
 changed:=pg_temp.save('taxonomy_term',jsonb_build_object('name','Locally adapted advice','code','advice','vocabulary_id',copy_vocab,'axis_id',copy_axis,'territories',jsonb_build_array(territory)),copy_child,copy_revision,copy_revision);PERFORM pg_temp.publish(changed,copy_revision);
 SELECT jsonb_agg(jsonb_build_object('term_id',rt.term_id,'revision_id',h.revision_id)) INTO members FROM taxonomy.release_terms rt JOIN governance.published_heads h ON h.entity_id=rt.term_id WHERE rt.release_id=copy;
 SELECT jsonb_agg(jsonb_build_object('axis_id',axis_id,'label',label,'sort_order',sort_order)) INTO axes FROM taxonomy.release_axes WHERE release_id=copy;
 next_copy:=governance.freeze_taxonomy_release(copy_vr,'v2',axes,members,'[]','Approve independent hierarchy edit');
 PERFORM pg_temp.assert_true((SELECT count(*)=1 FROM taxonomy.broader_links WHERE release_id=source) AND NOT EXISTS(SELECT FROM taxonomy.broader_links WHERE release_id=next_copy),'AC18 local hierarchy edit leaves source frozen');
 PERFORM pg_temp.assert_true(EXISTS(SELECT FROM governance.published_heads h JOIN i18n.revision_content_links l USING(revision_id) JOIN i18n.content_units c USING(content_id) WHERE h.entity_id=child AND l.field_code='name' AND c.original_text='Advice'),'AC18 local label edit leaves source label unchanged');
END $$;
ROLLBACK;
